SET DEFINE ON
SET SERVEROUTPUT ON
SET FEEDBACK ON
WHENEVER SQLERROR EXIT SQL.SQLCODE

PROMPT Preparing LLUSER as ADMIN...

DECLARE
  v_current_user VARCHAR2(128) := USER;
  v_exists NUMBER;
BEGIN
  IF v_current_user = 'ADMIN' THEN
    SELECT COUNT(*) INTO v_exists FROM dba_users WHERE username = 'LLUSER';
    IF v_exists = 0 THEN
      EXECUTE IMMEDIATE 'CREATE USER LLUSER IDENTIFIED' || ' BY "' || '&1' || '" DEFAULT TABLESPACE USERS TEMPORARY TABLESPACE TEMP QUOTA UNLIMITED ON USERS';
    ELSE
      BEGIN
        EXECUTE IMMEDIATE 'ALTER USER LLUSER IDENTIFIED' || ' BY "' || '&1' || '" ACCOUNT UNLOCK';
      EXCEPTION
        WHEN OTHERS THEN
          IF SQLCODE = -28007 THEN
            EXECUTE IMMEDIATE 'ALTER USER LLUSER ACCOUNT UNLOCK';
          ELSE
            RAISE;
          END IF;
      END;
      EXECUTE IMMEDIATE 'ALTER USER LLUSER DEFAULT TABLESPACE USERS TEMPORARY TABLESPACE TEMP QUOTA UNLIMITED ON USERS';
    END IF;
  ELSE
    RAISE_APPLICATION_ERROR(-20000, 'Run this loader as ADMIN. Current user: ' || v_current_user);
  END IF;
END;
/

GRANT CREATE SESSION TO LLUSER;
GRANT CREATE TABLE TO LLUSER;
GRANT CREATE VIEW TO LLUSER;
GRANT CREATE SEQUENCE TO LLUSER;
GRANT CREATE PROCEDURE TO LLUSER;
GRANT CREATE TYPE TO LLUSER;
GRANT CREATE MINING MODEL TO LLUSER;
GRANT UNLIMITED TABLESPACE TO LLUSER;
GRANT SODA_APP TO LLUSER;
GRANT GRAPH_DEVELOPER TO LLUSER;
GRANT EXECUTE ON MDSYS.SDO_GEOM TO LLUSER;
GRANT EXECUTE ON MDSYS.SDO_UTIL TO LLUSER;
GRANT EXECUTE ON DBMS_DATA_MINING TO LLUSER;
GRANT SELECT ON MINING MODEL ALL_MINILM_L12_V2 TO LLUSER;

CONNECT LLUSER/"&1"@&2
SET DEFINE OFF
SET SERVEROUTPUT ON
SET FEEDBACK ON

DECLARE
  v_expected_user VARCHAR2(30) := 'LLUSER';
BEGIN
  IF USER <> v_expected_user THEN
    RAISE_APPLICATION_ERROR(-20001, 'DDL/data section must run as LLUSER. Current user: ' || USER);
  END IF;
END;
/

PROMPT Dropping prior Life Sciences workshop objects...

DECLARE
  PROCEDURE exec_ignore(p_sql VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE p_sql;
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;
BEGIN
  exec_ignore('DROP PROPERTY GRAPH influencer_network');
  FOR model_name IN (
    SELECT column_value AS name
    FROM TABLE(sys.odcivarchar2list('DEMAND_SURGE_MODEL','CUSTOMER_SEGMENT_MODEL','REVENUE_PREDICT_MODEL','PRODUCT_CLUSTER_MODEL'))
  ) LOOP
    BEGIN
      DBMS_DATA_MINING.DROP_MODEL(model_name.name);
    EXCEPTION
      WHEN OTHERS THEN NULL;
    END;
  END LOOP;

  FOR object_name IN (
    SELECT column_value AS name
    FROM TABLE(sys.odcivarchar2list(
      'LS_OPERATIONS_DASHBOARD_V','LS_COLD_CHAIN_ROUTES_V','LS_SUPPLY_CAPACITY_V',
      'LS_COLD_CHAIN_SITES_V','LS_TRIAL_SITES_V','LS_CLINICAL_SUPPLY_ORDERS_V',
      'LS_SIGNAL_SOURCES_V','LS_QUALITY_SIGNALS_V','LS_REGULATED_PRODUCTS_V',
      'LS_MANUFACTURERS_V','OML_PRODUCT_CLUSTER_V','OML_REVENUE_TRAINING_V',
      'OML_CUSTOMER_RFM_V','OML_DEMAND_TRAINING_V','OML_CUSTOMER_SEGMENT_V',
      'PRODUCTS_INVENTORY_DV','ORDERS_DV','MEDIA_AUDIENCE_SIGNALS_V',
      'MEDIA_CAMPAIGN_ORDERS_V','MEDIA_CONTENT_ASSETS_V',
      'MEDIA_CREATOR_RELATIONSHIPS_V','MEDIA_DISTRIBUTION_CAPACITY_V'
    ))
  ) LOOP
    exec_ignore('DROP VIEW ' || object_name.name);
  END LOOP;

  FOR routine_name IN (
    SELECT column_value AS name
    FROM TABLE(sys.odcivarchar2list('SEARCH_PRODUCTS_BY_TEXT','REFRESH_MEDIA_VECTOR_ARTIFACTS'))
  ) LOOP
    exec_ignore('DROP FUNCTION ' || routine_name.name);
    exec_ignore('DROP PROCEDURE ' || routine_name.name);
  END LOOP;

  FOR table_name IN (
    SELECT column_value AS name
    FROM TABLE(sys.odcivarchar2list(
      'SEMANTIC_MATCHES','POST_EMBEDDINGS','PRODUCT_EMBEDDINGS',
      'SHIPMENTS','ORDER_ITEMS','ORDERS','BRAND_INFLUENCER_LINKS',
      'INFLUENCER_CONNECTIONS','POST_PRODUCT_MENTIONS','SOCIAL_POSTS',
      'INVENTORY','CUSTOMERS','INFLUENCERS','FULFILLMENT_CENTERS',
      'PRODUCTS','BRANDS','DEMAND_SURGE_SETTINGS','CUSTOMER_SEGMENT_SETTINGS',
      'REVENUE_PREDICT_SETTINGS','PROD_CLUSTER_SETTINGS'
    ))
  ) LOOP
    exec_ignore('DROP TABLE ' || table_name.name || ' CASCADE CONSTRAINTS PURGE');
  END LOOP;

  DELETE FROM user_sdo_geom_metadata
  WHERE table_name IN ('FULFILLMENT_CENTERS','CUSTOMERS');
  COMMIT;
END;
/

PROMPT Creating schema objects...

CREATE TABLE brands (
  brand_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  brand_name VARCHAR2(200) NOT NULL,
  brand_slug VARCHAR2(100) NOT NULL UNIQUE,
  brand_category VARCHAR2(100),
  headquarters_city VARCHAR2(100),
  headquarters_lat NUMBER(10,7),
  headquarters_lon NUMBER(11,7),
  founded_year NUMBER(4),
  annual_revenue NUMBER(15,2),
  social_tier VARCHAR2(20) CHECK (social_tier IN ('emerging','standard','premium','luxury')),
  created_at TIMESTAMP,
  updated_at TIMESTAMP
);

CREATE TABLE products (
  product_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  brand_id NUMBER NOT NULL REFERENCES brands(brand_id),
  sku VARCHAR2(50) NOT NULL UNIQUE,
  product_name VARCHAR2(300) NOT NULL,
  description CLOB,
  category VARCHAR2(100),
  subcategory VARCHAR2(100),
  unit_price NUMBER(10,2) NOT NULL,
  unit_cost NUMBER(10,2),
  weight_kg NUMBER(8,3),
  is_active NUMBER(1),
  launch_date DATE,
  tags VARCHAR2(1000),
  created_at TIMESTAMP,
  updated_at TIMESTAMP
);

CREATE TABLE fulfillment_centers (
  center_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  center_name VARCHAR2(200) NOT NULL,
  center_type VARCHAR2(30) CHECK (center_type IN ('warehouse','distribution','micro','drop_ship','store')),
  address_line1 VARCHAR2(300),
  city VARCHAR2(100),
  state_province VARCHAR2(100),
  postal_code VARCHAR2(20),
  country VARCHAR2(3),
  latitude NUMBER(10,7) NOT NULL,
  longitude NUMBER(11,7) NOT NULL,
  capacity_units NUMBER(10),
  current_load_pct NUMBER(5,2),
  is_active NUMBER(1),
  operating_hours VARCHAR2(50),
  created_at TIMESTAMP,
  location SDO_GEOMETRY
);

CREATE TABLE inventory (
  inventory_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  product_id NUMBER NOT NULL REFERENCES products(product_id),
  center_id NUMBER NOT NULL REFERENCES fulfillment_centers(center_id),
  quantity_on_hand NUMBER(10),
  quantity_reserved NUMBER(10),
  quantity_incoming NUMBER(10),
  reorder_point NUMBER(10),
  reorder_qty NUMBER(10),
  last_restock_date DATE,
  updated_at TIMESTAMP,
  CONSTRAINT uq_inventory UNIQUE (product_id, center_id)
);

CREATE TABLE customers (
  customer_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  email VARCHAR2(300) NOT NULL UNIQUE,
  first_name VARCHAR2(100),
  last_name VARCHAR2(100),
  city VARCHAR2(100),
  state_province VARCHAR2(100),
  postal_code VARCHAR2(20),
  country VARCHAR2(3),
  latitude NUMBER(10,7),
  longitude NUMBER(11,7),
  location SDO_GEOMETRY,
  customer_tier VARCHAR2(20) CHECK (customer_tier IN ('new','standard','preferred','vip')),
  lifetime_value NUMBER(12,2),
  created_at TIMESTAMP
);

CREATE TABLE orders (
  order_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  customer_id NUMBER NOT NULL REFERENCES customers(customer_id),
  order_status VARCHAR2(30) CHECK (order_status IN ('pending','confirmed','processing','shipped','delivered','cancelled','returned')),
  order_total NUMBER(12,2),
  shipping_cost NUMBER(8,2),
  fulfillment_center_id NUMBER REFERENCES fulfillment_centers(center_id),
  shipping_lat NUMBER(10,7),
  shipping_lon NUMBER(11,7),
  estimated_delivery DATE,
  actual_delivery DATE,
  social_source_id NUMBER,
  demand_score NUMBER(5,2),
  created_at TIMESTAMP,
  updated_at TIMESTAMP
);

CREATE TABLE order_items (
  item_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  order_id NUMBER NOT NULL REFERENCES orders(order_id),
  product_id NUMBER NOT NULL REFERENCES products(product_id),
  quantity NUMBER(6) NOT NULL,
  unit_price NUMBER(10,2) NOT NULL,
  line_total NUMBER(12,2) GENERATED ALWAYS AS (quantity * unit_price) VIRTUAL,
  fulfilled_from NUMBER REFERENCES fulfillment_centers(center_id)
);

CREATE TABLE influencers (
  influencer_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  handle VARCHAR2(200) NOT NULL UNIQUE,
  display_name VARCHAR2(200),
  platform VARCHAR2(50) CHECK (platform IN ('instagram','tiktok','twitter','youtube','threads')),
  follower_count NUMBER(12),
  engagement_rate NUMBER(5,4),
  influence_score NUMBER(5,2),
  niche VARCHAR2(100),
  city VARCHAR2(100),
  region VARCHAR2(100),
  country VARCHAR2(3),
  is_verified NUMBER(1),
  created_at TIMESTAMP
);

CREATE TABLE social_posts (
  post_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  influencer_id NUMBER REFERENCES influencers(influencer_id),
  platform VARCHAR2(50),
  external_post_id VARCHAR2(200),
  post_text CLOB,
  posted_at TIMESTAMP NOT NULL,
  likes_count NUMBER(10),
  shares_count NUMBER(10),
  comments_count NUMBER(10),
  views_count NUMBER(12),
  sentiment_score NUMBER(4,3),
  virality_score NUMBER(5,2),
  detected_products VARCHAR2(2000),
  momentum_flag VARCHAR2(20) CHECK (momentum_flag IN ('normal','rising','viral','mega_viral')),
  processed_at TIMESTAMP,
  created_at TIMESTAMP
);

CREATE TABLE post_product_mentions (
  mention_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  post_id NUMBER NOT NULL REFERENCES social_posts(post_id),
  product_id NUMBER NOT NULL REFERENCES products(product_id),
  confidence_score NUMBER(4,3),
  mention_type VARCHAR2(30) CHECK (mention_type IN ('direct','semantic','hashtag','visual','inferred')),
  created_at TIMESTAMP,
  CONSTRAINT uq_post_product UNIQUE (post_id, product_id)
);

CREATE TABLE influencer_connections (
  connection_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  from_influencer NUMBER NOT NULL REFERENCES influencers(influencer_id),
  to_influencer NUMBER NOT NULL REFERENCES influencers(influencer_id),
  connection_type VARCHAR2(30) NOT NULL CHECK (connection_type IN ('follows','collaborates','mentioned','reshared','tagged','duet','inspired_by')),
  strength NUMBER(4,3),
  interaction_count NUMBER(8),
  first_seen TIMESTAMP,
  last_interaction TIMESTAMP,
  CONSTRAINT uq_connection UNIQUE (from_influencer, to_influencer, connection_type)
);

CREATE TABLE brand_influencer_links (
  link_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  brand_id NUMBER NOT NULL REFERENCES brands(brand_id),
  influencer_id NUMBER NOT NULL REFERENCES influencers(influencer_id),
  relationship_type VARCHAR2(30) CHECK (relationship_type IN ('organic','sponsored','ambassador','affiliate','competitor_mention')),
  post_count NUMBER(8),
  avg_engagement NUMBER(8,4),
  revenue_attributed NUMBER(12,2),
  first_mention TIMESTAMP,
  last_mention TIMESTAMP,
  CONSTRAINT uq_brand_inf UNIQUE (brand_id, influencer_id)
);

CREATE TABLE shipments (
  shipment_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  order_id NUMBER NOT NULL REFERENCES orders(order_id),
  center_id NUMBER NOT NULL REFERENCES fulfillment_centers(center_id),
  carrier VARCHAR2(100),
  tracking_number VARCHAR2(200),
  ship_status VARCHAR2(30) CHECK (ship_status IN ('preparing','picked','packed','shipped','in_transit','out_for_delivery','delivered','exception')),
  distance_km NUMBER(8,2),
  estimated_hours NUMBER(6,2),
  ship_cost NUMBER(8,2),
  shipped_at TIMESTAMP,
  delivered_at TIMESTAMP,
  created_at TIMESTAMP
);

