PROMPT Rebuilding spatial metadata and generated artifacts...

UPDATE fulfillment_centers
SET location = SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(longitude, latitude, NULL), NULL, NULL)
WHERE latitude IS NOT NULL AND longitude IS NOT NULL;

UPDATE customers
SET location = SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(longitude, latitude, NULL), NULL, NULL)
WHERE latitude IS NOT NULL AND longitude IS NOT NULL;

INSERT INTO user_sdo_geom_metadata (table_name, column_name, diminfo, srid)
VALUES ('FULFILLMENT_CENTERS', 'LOCATION',
  SDO_DIM_ARRAY(SDO_DIM_ELEMENT('LON', -180, 180, 0.005), SDO_DIM_ELEMENT('LAT', -90, 90, 0.005)), 4326);

INSERT INTO user_sdo_geom_metadata (table_name, column_name, diminfo, srid)
VALUES ('CUSTOMERS', 'LOCATION',
  SDO_DIM_ARRAY(SDO_DIM_ELEMENT('LON', -180, 180, 0.005), SDO_DIM_ELEMENT('LAT', -90, 90, 0.005)), 4326);

CREATE INDEX idx_fc_spatial ON fulfillment_centers(location) INDEXTYPE IS MDSYS.SPATIAL_INDEX_V2;
CREATE INDEX idx_cust_spatial ON customers(location) INDEXTYPE IS MDSYS.SPATIAL_INDEX_V2;

CREATE OR REPLACE JSON RELATIONAL DUALITY VIEW orders_dv AS
SELECT JSON {
    '_id'         : o.order_id,
    'customerId'  : o.customer_id,
    'status'      : o.order_status,
    'total'       : o.order_total,
    'shippingCost': o.shipping_cost,
    'demandScore' : o.demand_score,
    'createdAt'   : o.created_at,
    'items' : [
        SELECT JSON {
            'itemId'    : oi.item_id,
            'productId' : oi.product_id,
            'quantity'  : oi.quantity,
            'unitPrice' : oi.unit_price
        }
        FROM order_items oi WITH UPDATE
        WHERE oi.order_id = o.order_id
    ]
}
FROM orders o WITH UPDATE;

CREATE OR REPLACE JSON RELATIONAL DUALITY VIEW products_inventory_dv AS
SELECT JSON {
    '_id'          : p.product_id,
    'sku'          : p.sku,
    'productName'  : p.product_name,
    'category'     : p.category,
    'unitPrice'    : p.unit_price,
    'brand'        : (SELECT b.brand_name FROM brands b WHERE b.brand_id = p.brand_id),
    'inventory'    : [
        SELECT JSON {
            'centerId'        : i.center_id,
            'quantityOnHand'  : i.quantity_on_hand,
            'quantityReserved': i.quantity_reserved
        }
        FROM inventory i WITH UPDATE
        WHERE i.product_id = p.product_id
    ]
}
FROM products p WITH UPDATE;

CREATE TABLE product_embeddings (
  embedding_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  product_id NUMBER NOT NULL REFERENCES products(product_id),
  embedding_model VARCHAR2(100),
  embedding_text CLOB,
  embedding VECTOR(384),
  created_at TIMESTAMP,
  CONSTRAINT uq_ls_prod_embed UNIQUE (product_id, embedding_model)
);

CREATE TABLE post_embeddings (
  embedding_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  post_id NUMBER NOT NULL REFERENCES social_posts(post_id),
  embedding_model VARCHAR2(100),
  embedding_text CLOB,
  embedding VECTOR(384),
  created_at TIMESTAMP,
  CONSTRAINT uq_ls_post_embed UNIQUE (post_id, embedding_model)
);

CREATE TABLE semantic_matches (
  match_id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
  post_id NUMBER NOT NULL REFERENCES social_posts(post_id),
  product_id NUMBER NOT NULL REFERENCES products(product_id),
  similarity_score NUMBER(6,5),
  match_rank NUMBER(4),
  match_method VARCHAR2(30) CHECK (match_method IN ('vector','keyword','hybrid','visual')),
  verified NUMBER(1),
  created_at TIMESTAMP
);

INSERT INTO product_embeddings (product_id, embedding_model, embedding_text, embedding, created_at)
SELECT product_id,
       'all_MiniLM_L12_v2',
       product_name || ' ' || category || ' ' || subcategory || ' ' || tags,
       VECTOR_EMBEDDING(ADMIN.ALL_MINILM_L12_V2 USING product_name || ' ' || category || ' ' || subcategory || ' ' || tags AS DATA),
       TIMESTAMP '2026-07-27 00:00:00'
FROM products
WHERE is_active = 1;

INSERT INTO post_embeddings (post_id, embedding_model, embedding_text, embedding, created_at)
SELECT post_id,
       'all_MiniLM_L12_v2',
       DBMS_LOB.SUBSTR(post_text, 4000, 1),
       VECTOR_EMBEDDING(ADMIN.ALL_MINILM_L12_V2 USING DBMS_LOB.SUBSTR(post_text, 4000, 1) AS DATA),
       TIMESTAMP '2026-07-27 00:00:00'
FROM social_posts
WHERE post_text IS NOT NULL;

CREATE PROPERTY GRAPH influencer_network
    VERTEX TABLES (
        influencers KEY (influencer_id)
            LABEL influencer
            PROPERTIES (influencer_id, handle, display_name, platform, follower_count, engagement_rate, influence_score, niche, city, region, is_verified),
        brands KEY (brand_id)
            LABEL brand
            PROPERTIES (brand_id, brand_name, brand_category, social_tier),
        products KEY (product_id)
            LABEL product
            PROPERTIES (product_id, product_name, category, unit_price),
        social_posts KEY (post_id)
            LABEL social_post
            PROPERTIES (post_id, platform, posted_at, virality_score, momentum_flag)
    )
    EDGE TABLES (
        influencer_connections
            KEY (connection_id)
            SOURCE KEY (from_influencer) REFERENCES influencers (influencer_id)
            DESTINATION KEY (to_influencer) REFERENCES influencers (influencer_id)
            LABEL connects_to
            PROPERTIES (connection_type, strength, interaction_count),
        brand_influencer_links
            KEY (link_id)
            SOURCE KEY (influencer_id) REFERENCES influencers (influencer_id)
            DESTINATION KEY (brand_id) REFERENCES brands (brand_id)
            LABEL promotes
            PROPERTIES (relationship_type, post_count, avg_engagement, revenue_attributed),
        post_product_mentions
            KEY (mention_id)
            SOURCE KEY (post_id) REFERENCES social_posts (post_id)
            DESTINATION KEY (product_id) REFERENCES products (product_id)
            LABEL mentions_product
            PROPERTIES (confidence_score, mention_type)
    );

CREATE OR REPLACE VIEW ls_manufacturers_v AS
SELECT brand_id AS manufacturer_id, brand_name AS manufacturer_name, brand_category AS manufacturer_type,
       headquarters_city, annual_revenue
FROM brands;

CREATE OR REPLACE VIEW ls_regulated_products_v AS
SELECT product_id AS regulated_product_id, product_name AS regulated_product_name, category AS product_category,
       subcategory, unit_price AS unit_supply_value, tags, brand_id AS manufacturer_id
FROM products;

CREATE OR REPLACE VIEW ls_quality_signals_v AS
SELECT post_id AS signal_id, post_text AS signal_text, platform AS source_channel,
       virality_score AS criticality_score, momentum_flag AS severity_band,
       views_count AS exposure_count, likes_count AS acknowledgement_count,
       shares_count AS escalation_count, comments_count AS cases_opened_count,
       posted_at AS signal_time, influencer_id AS source_id
FROM social_posts;

CREATE OR REPLACE VIEW ls_signal_sources_v AS
SELECT influencer_id AS source_id, handle AS source_code, display_name AS source_name,
       CASE platform
         WHEN 'instagram' THEN 'FDA bulletin'
         WHEN 'tiktok' THEN 'Quality event'
         WHEN 'twitter' THEN 'EMA/FDA notice'
         WHEN 'youtube' THEN 'Cold-chain advisory'
         WHEN 'threads' THEN 'Manufacturer update'
         ELSE platform
       END AS source_channel,
       follower_count AS source_reach, influence_score AS source_authority_score, region
FROM influencers;

CREATE OR REPLACE VIEW ls_clinical_supply_orders_v AS
SELECT o.order_id AS clinical_supply_order_id, o.customer_id AS trial_site_id,
       c.first_name || ' ' || c.last_name AS trial_site_name,
       o.order_status AS clinical_supply_status, o.order_total AS supply_value_exposure,
       o.shipping_cost AS route_cost, o.fulfillment_center_id AS cold_chain_site_id,
       fc.center_name AS cold_chain_fulfillment_site, o.social_source_id AS quality_signal_id,
       o.demand_score AS urgency_score, o.created_at, o.updated_at
FROM orders o
JOIN customers c ON c.customer_id = o.customer_id
LEFT JOIN fulfillment_centers fc ON fc.center_id = o.fulfillment_center_id;

CREATE OR REPLACE VIEW ls_trial_sites_v AS
SELECT customer_id AS trial_site_id, email AS site_contact_email, first_name || ' ' || last_name AS trial_site_name,
       city, state_province, postal_code, country, latitude, longitude, location,
       customer_tier AS trial_site_tier, lifetime_value AS historical_supply_value
FROM customers;

CREATE OR REPLACE VIEW ls_cold_chain_sites_v AS
SELECT center_id AS cold_chain_site_id, center_name AS cold_chain_site_name,
       CASE center_type
         WHEN 'distribution' THEN 'Regional Cold-Chain Hub'
         WHEN 'warehouse' THEN 'GMP Warehouse'
         WHEN 'micro' THEN 'Clinical Trial Depot'
         WHEN 'store' THEN 'Clinical Trial Depot'
         WHEN 'drop_ship' THEN 'Partner Logistics Point'
         ELSE center_type
       END AS cold_chain_site_type,
       city, state_province, latitude, longitude, capacity_units AS controlled_storage_capacity,
       current_load_pct AS utilization_pct, is_active
FROM fulfillment_centers;

CREATE OR REPLACE VIEW ls_supply_capacity_v AS
SELECT inventory_id AS capacity_id, product_id AS regulated_product_id, center_id AS cold_chain_site_id,
       quantity_on_hand AS available_units, quantity_reserved AS reserved_units, quantity_incoming AS incoming_units,
       reorder_point AS minimum_supply_threshold, reorder_qty AS target_replenishment_increment, updated_at
FROM inventory;

CREATE OR REPLACE VIEW ls_cold_chain_routes_v AS
SELECT shipment_id AS route_id, order_id AS clinical_supply_order_id, center_id AS cold_chain_site_id,
       carrier AS route_provider, tracking_number AS route_reference, ship_status AS cold_chain_route_status,
       distance_km, estimated_hours, ship_cost AS route_cost, shipped_at, delivered_at, created_at
FROM shipments;

CREATE OR REPLACE VIEW ls_operations_dashboard_v AS
SELECT o.order_id AS clinical_supply_order_id, o.order_status AS clinical_supply_status,
       o.order_total AS supply_value_exposure, o.social_source_id AS quality_signal_id,
       o.demand_score AS urgency_score, o.created_at, p.product_name,
       p.category AS product_category, b.brand_name AS manufacturer_name
FROM orders o
JOIN order_items oi ON oi.order_id = o.order_id
JOIN products p ON p.product_id = oi.product_id
JOIN brands b ON b.brand_id = p.brand_id;

CREATE OR REPLACE VIEW oml_demand_training_v AS
WITH product_features AS (
  SELECT p.product_id, p.category, p.unit_price,
         NVL(eng.total_posts, 0) AS total_posts, NVL(eng.avg_sentiment, 0.5) AS avg_sentiment,
         NVL(eng.total_likes, 0) AS total_likes, NVL(eng.total_shares, 0) AS total_shares,
         NVL(eng.total_views, 0) AS total_views, NVL(eng.avg_virality, 0) AS avg_virality,
         NVL(eng.viral_posts, 0) AS viral_posts, NVL(eng.rising_posts, 0) AS rising_posts,
         NVL(sales.units_sold, 0) AS units_sold, NVL(sales.revenue, 0) AS revenue
  FROM products p
  LEFT JOIN (
    SELECT ppm.product_id, COUNT(*) AS total_posts, AVG(sp.sentiment_score) AS avg_sentiment,
           SUM(sp.likes_count) AS total_likes, SUM(sp.shares_count) AS total_shares,
           SUM(sp.views_count) AS total_views, AVG(sp.virality_score) AS avg_virality,
           SUM(CASE WHEN sp.momentum_flag IN ('viral', 'mega_viral') THEN 1 ELSE 0 END) AS viral_posts,
           SUM(CASE WHEN sp.momentum_flag = 'rising' THEN 1 ELSE 0 END) AS rising_posts
    FROM post_product_mentions ppm
    JOIN social_posts sp ON sp.post_id = ppm.post_id
    GROUP BY ppm.product_id
  ) eng ON eng.product_id = p.product_id
  LEFT JOIN (
    SELECT product_id, SUM(quantity) AS units_sold, SUM(line_total) AS revenue
    FROM order_items
    GROUP BY product_id
  ) sales ON sales.product_id = p.product_id
  WHERE p.is_active = 1
)
SELECT product_id, category, unit_price, total_posts, avg_sentiment, total_likes, total_shares,
       total_views, avg_virality, viral_posts, rising_posts, units_sold, revenue,
       CASE
         WHEN avg_virality >= 70 OR viral_posts >= 4 OR total_views >= 10000000 THEN 'SURGE'
         WHEN avg_virality >= 45 OR rising_posts >= 5 OR total_views >= 2500000 THEN 'WATCH'
         ELSE 'STABLE'
       END AS surge_flag
FROM product_features;

CREATE OR REPLACE VIEW oml_customer_rfm_v AS
SELECT c.customer_id, NVL(c.lifetime_value, 0) AS lifetime_value,
       NVL(rfm.recency_days, 999) AS recency_days, NVL(rfm.frequency, 0) AS frequency,
       NVL(rfm.monetary, 0) AS monetary, NVL(rfm.avg_order_value, 0) AS avg_order_value,
       NVL(rfm.total_items, 0) AS total_items
FROM customers c
LEFT JOIN (
  SELECT o.customer_id,
         ROUND((SELECT MAX(CAST(created_at AS DATE)) FROM orders) - CAST(MAX(o.created_at) AS DATE)) AS recency_days,
         COUNT(DISTINCT o.order_id) AS frequency, SUM(o.order_total) AS monetary,
         AVG(o.order_total) AS avg_order_value, NVL(SUM(oi_cnt.item_count), 0) AS total_items
  FROM orders o
  LEFT JOIN (
    SELECT order_id, SUM(quantity) AS item_count
    FROM order_items
    GROUP BY order_id
  ) oi_cnt ON oi_cnt.order_id = o.order_id
  GROUP BY o.customer_id
) rfm ON rfm.customer_id = c.customer_id
WHERE NVL(rfm.frequency, 0) > 0;

CREATE OR REPLACE VIEW oml_revenue_training_v AS
SELECT o.order_id, o.order_total AS target_revenue, c.customer_tier, NVL(c.lifetime_value, 0) AS lifetime_value,
       NVL(o.demand_score, 0) AS demand_score, NVL(o.shipping_cost, 0) AS shipping_cost,
       CASE WHEN o.social_source_id IS NULL THEN 0 ELSE 1 END AS social_signal_flag,
       NVL(items.item_count, 0) AS item_count, NVL(items.distinct_products, 0) AS distinct_products,
       NVL(items.avg_unit_price, 0) AS avg_unit_price, NVL(items.max_unit_price, 0) AS max_unit_price
FROM orders o
JOIN customers c ON c.customer_id = o.customer_id
LEFT JOIN (
  SELECT order_id, SUM(quantity) AS item_count, COUNT(DISTINCT product_id) AS distinct_products,
         AVG(unit_price) AS avg_unit_price, MAX(unit_price) AS max_unit_price
  FROM order_items
  GROUP BY order_id
) items ON items.order_id = o.order_id
WHERE o.order_total IS NOT NULL;

CREATE OR REPLACE VIEW oml_product_cluster_v AS
SELECT p.product_id, p.unit_price, NVL(p.weight_kg, 0) AS weight_kg,
       NVL(sales.units_sold, 0) AS units_sold, NVL(sales.revenue, 0) AS revenue,
       NVL(sales.order_count, 0) AS order_count, NVL(eng.total_engagement, 0) AS total_engagement,
       NVL(eng.avg_sentiment, 0.5) AS avg_sentiment, NVL(eng.avg_virality, 0) AS avg_virality
FROM products p
LEFT JOIN (
  SELECT product_id, SUM(quantity) AS units_sold, SUM(line_total) AS revenue, COUNT(DISTINCT order_id) AS order_count
  FROM order_items
  GROUP BY product_id
) sales ON sales.product_id = p.product_id
LEFT JOIN (
  SELECT ppm.product_id, SUM(sp.likes_count + sp.shares_count + sp.comments_count + sp.views_count) AS total_engagement,
         AVG(sp.sentiment_score) AS avg_sentiment, AVG(sp.virality_score) AS avg_virality
  FROM post_product_mentions ppm
  JOIN social_posts sp ON sp.post_id = ppm.post_id
  GROUP BY ppm.product_id
) eng ON eng.product_id = p.product_id
WHERE p.is_active = 1;

DECLARE
  PROCEDURE reset_settings_table(p_table_name VARCHAR2, p_algo VARCHAR2, p_clusters NUMBER DEFAULT NULL) IS
  BEGIN
    EXECUTE IMMEDIATE 'CREATE TABLE ' || p_table_name || ' (setting_name VARCHAR2(30), setting_value VARCHAR2(4000))';
    EXECUTE IMMEDIATE 'INSERT INTO ' || p_table_name || ' VALUES (:1, :2)'
      USING DBMS_DATA_MINING.ALGO_NAME, p_algo;
    EXECUTE IMMEDIATE 'INSERT INTO ' || p_table_name || ' VALUES (:1, :2)'
      USING DBMS_DATA_MINING.PREP_AUTO, DBMS_DATA_MINING.PREP_AUTO_ON;
    IF p_clusters IS NOT NULL THEN
      EXECUTE IMMEDIATE 'INSERT INTO ' || p_table_name || ' VALUES (:1, :2)'
        USING DBMS_DATA_MINING.CLUS_NUM_CLUSTERS, TO_CHAR(p_clusters);
    END IF;
  END;
BEGIN
  reset_settings_table('DEMAND_SURGE_SETTINGS', DBMS_DATA_MINING.ALGO_RANDOM_FOREST);
  reset_settings_table('CUSTOMER_SEGMENT_SETTINGS', DBMS_DATA_MINING.ALGO_KMEANS, 4);
  reset_settings_table('REVENUE_PREDICT_SETTINGS', DBMS_DATA_MINING.ALGO_GENERALIZED_LINEAR_MODEL);
  reset_settings_table('PROD_CLUSTER_SETTINGS', DBMS_DATA_MINING.ALGO_KMEANS, 5);

  DBMS_DATA_MINING.CREATE_MODEL(
    model_name => 'DEMAND_SURGE_MODEL',
    mining_function => DBMS_DATA_MINING.CLASSIFICATION,
    data_table_name => 'OML_DEMAND_TRAINING_V',
    case_id_column_name => 'PRODUCT_ID',
    target_column_name => 'SURGE_FLAG',
    settings_table_name => 'DEMAND_SURGE_SETTINGS'
  );

  DBMS_DATA_MINING.CREATE_MODEL(
    model_name => 'CUSTOMER_SEGMENT_MODEL',
    mining_function => DBMS_DATA_MINING.CLUSTERING,
    data_table_name => 'OML_CUSTOMER_RFM_V',
    case_id_column_name => 'CUSTOMER_ID',
    settings_table_name => 'CUSTOMER_SEGMENT_SETTINGS'
  );

  DBMS_DATA_MINING.CREATE_MODEL(
    model_name => 'REVENUE_PREDICT_MODEL',
    mining_function => DBMS_DATA_MINING.REGRESSION,
    data_table_name => 'OML_REVENUE_TRAINING_V',
    case_id_column_name => 'ORDER_ID',
    target_column_name => 'TARGET_REVENUE',
    settings_table_name => 'REVENUE_PREDICT_SETTINGS'
  );

  DBMS_DATA_MINING.CREATE_MODEL(
    model_name => 'PRODUCT_CLUSTER_MODEL',
    mining_function => DBMS_DATA_MINING.CLUSTERING,
    data_table_name => 'OML_PRODUCT_CLUSTER_V',
    case_id_column_name => 'PRODUCT_ID',
    settings_table_name => 'PROD_CLUSTER_SETTINGS'
  );
END;
/

COMMIT;

PROMPT Validation summary...

SELECT 'INVALID_OBJECTS' AS check_name, COUNT(*) AS check_value
FROM user_objects
WHERE status <> 'VALID'
UNION ALL SELECT 'MANUFACTURERS', COUNT(*) FROM brands
UNION ALL SELECT 'REGULATED_PRODUCTS', COUNT(*) FROM products
UNION ALL SELECT 'QUALITY_SIGNALS', COUNT(*) FROM social_posts
UNION ALL SELECT 'CLINICAL_SUPPLY_ORDERS', COUNT(*) FROM orders
UNION ALL SELECT 'TRIAL_SITES', COUNT(*) FROM customers
UNION ALL SELECT 'COLD_CHAIN_SITES', COUNT(*) FROM fulfillment_centers
UNION ALL SELECT 'SUPPLY_CAPACITY_ROWS', COUNT(*) FROM inventory
UNION ALL SELECT 'COLD_CHAIN_ROUTES', COUNT(*) FROM shipments
UNION ALL SELECT 'PRODUCT_EMBEDDINGS', COUNT(*) FROM product_embeddings
UNION ALL SELECT 'SIGNAL_EMBEDDINGS', COUNT(*) FROM post_embeddings
UNION ALL SELECT 'OML_MODELS', COUNT(*) FROM user_mining_models
WHERE model_name IN ('DEMAND_SURGE_MODEL','CUSTOMER_SEGMENT_MODEL','REVENUE_PREDICT_MODEL','PRODUCT_CLUSTER_MODEL');

EXIT
